  --kavia-dark: #1A1A1A;
  --text-color: #fff;
  --text-secondary: rgba(255, 255, 255, 0.7);
  --border-color: rgba(255, 255, 255, 0.1);
  --primary: #6C2EBE;
  --secondary: #F5F6FA;
  --surface: #fff;
  --expense: #E74C3C;
  --income: #22C55E;
}

html,
body {
  min-height: 100%;
  font-family: "Inter", "Segoe UI", Arial, sans-serif;
  background: var(--secondary, #F5F6FA);
  color: var(--kavia-dark);
  margin: 0;
  padding: 0;
}

.app {
  display: flex;
  min-height: 100vh;
  background: var(--secondary, #F5F6FA);
}

/* Main Content */
.main-content {
  flex: 1 1 0%;
  padding: 0 28px;
  min-width: 0;
  margin-top: 0;
}

.container {
  background: var(--surface, #fff);
  border-radius: 10px;
  margin: 0 auto;
  padding: 24px 18px;
  box-shadow: 0 1px 8px rgba(41,21,102,0.08);
}

.title {
  font-size: 2.1rem;
  font-weight: 700;
  color: var(--primary, #6C2EBE);
  margin: 14px 0;
}

.subtitle {
  font-size: 1.23rem;
  font-weight: 500;
  color: var(--kavia-dark, #222);
  margin: 9px 0 13px 0;
}

.btn, .btn-large, .btn-cancel {
  border-radius: 6px;
  border: none;
  cursor: pointer;
  font-weight: 600;
  outline: none;
  padding: 8px 20px;
  margin-top: 7px;
  font-size: 1em;
  transition: background 0.18s, color 0.18s;
}

.btn {
  background: var(--primary, #6C2EBE);
  color: #fff;
}
.btn:hover, .btn:focus {
  background: #5320a8;
}

/* Large primary button */
.btn-large {
  background: var(--primary, #6C2EBE);
  color: #fff;
  padding: 12px 23px;
  font-size: 1.13em;
}

.btn-cancel {
  background: #eceaf2;
  color: var(--primary, #6C2EBE);
}
.btn-cancel:hover {
  background: #f5f1fe;
  color: var(--expense, #E74C3C);
}

/* Utility classes */
.text-center {
  text-align: center;
}

/* Responsive tweaks */
@media (max-width: 680px) {
  .main-content {
    padding: 0 4vw;
  }
  .container {
    padding: 12px 6vw;
  }
}
